document.addEventListener('DOMContentLoaded', function () {

    let eventosGuardados = JSON.parse(localStorage.getItem("eventos")) || [];
  
    let calendarEl = document.getElementById('calendar');
  
    let calendar = new FullCalendar.Calendar(calendarEl, {
      initialView: 'dayGridMonth',
      selectable: true,
      editable: true,
  
      events: eventosGuardados,
  
      dateClick: function (info) {
        let titulo = prompt("Título del evento:");
        let descripcion = prompt("Descripción:");
  
        if (titulo) {
          let nuevoEvento = {
            title: titulo,
            start: info.dateStr,
            extendedProps: {
              descripcion: descripcion
            }
          };
  
          calendar.addEvent(nuevoEvento);
          eventosGuardados.push(nuevoEvento);
          localStorage.setItem("eventos", JSON.stringify(eventosGuardados));
        }
      },
  
      eventClick: function (info) {
        alert(
          "📌 " + info.event.title +
          "\n📝 " + (info.event.extendedProps.descripcion || "Sin descripción")
        );
      }
    });
  
    calendar.render();
  });
  